INSERT INTO `aura_theme_banners` (id, biller_id, position, title, subtitle, image, link_url, button_text, sort_order, badge, badge_color, badge_bg, coupon_code, original_price, promo_price, savings, valid_until, accent_color, status) VALUES (1, 3, 'home_promo', 'Spanish Iced Latte & Almond Croissant', 'Signature single-origin espresso with sweetened milk paired with flaky 84% butter pastry.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=800&auto=format&fit=crop&q=80', '/shop/sbc-store', 'Claim 25% Off Deal', 1, 'DAILY FLASH DEAL • 25% OFF', '#ef4444', 'rgba(239, 68, 68, 0.95)', 'AURACOFFEE25', 12.25, 8.99, 'Save $3.26', 'Today only until 3:00 PM', '#2F6FED', 1) ON DUPLICATE KEY UPDATE title = VALUES(title), subtitle = VALUES(subtitle), image = VALUES(image), promo_price = VALUES(promo_price), coupon_code = VALUES(coupon_code);
INSERT INTO `aura_theme_banners` (id, biller_id, position, title, subtitle, image, link_url, button_text, sort_order, badge, badge_color, badge_bg, coupon_code, original_price, promo_price, savings, valid_until, accent_color, status) VALUES (2, 251, 'home_promo', 'Golden Viennoiserie & Sourdough Box', 'Warm Normandy butter croissants, pain au chocolat, and rustic country sourdough loaves.', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', '/shop/aura-bakery', 'Claim Bakery Deal', 2, 'WEEKEND SPECIAL • BUY 1 GET 1 50% OFF', '#f59e0b', 'rgba(245, 158, 11, 0.95)', 'BAKERY50', 18.5, 12.75, 'Save $5.75', 'Fresh morning bake', '#FF7A3D', 1) ON DUPLICATE KEY UPDATE title = VALUES(title), subtitle = VALUES(subtitle), image = VALUES(image), promo_price = VALUES(promo_price), coupon_code = VALUES(coupon_code);
INSERT INTO `aura_theme_banners` (id, biller_id, position, title, subtitle, image, link_url, button_text, sort_order, badge, badge_color, badge_bg, coupon_code, original_price, promo_price, savings, valid_until, accent_color, status) VALUES (3, 252, 'home_promo', 'Kyoto Uji Matcha Latte & Mochi Waffle', 'First-harvest ceremonial matcha stone-ground in Uji, whisked fresh with oat milk.', 'https://images.unsplash.com/photo-1536256263959-770b48d82b0a?w=800&auto=format&fit=crop&q=80', '/shop/aura-lounge', 'Explore Matcha Deal', 3, 'CEREMONIAL SPECIAL • 20% OFF', '#10b981', 'rgba(16, 185, 129, 0.95)', 'MATCHA20', 14, 10.5, 'Save $3.50', 'Available daily 11am-8pm', '#10b981', 1) ON DUPLICATE KEY UPDATE title = VALUES(title), subtitle = VALUES(subtitle), image = VALUES(image), promo_price = VALUES(promo_price), coupon_code = VALUES(coupon_code);
INSERT INTO `aura_theme_banners` (id, biller_id, position, title, subtitle, image, link_url, button_text, sort_order, badge, badge_color, badge_bg, coupon_code, original_price, promo_price, savings, valid_until, accent_color, status) VALUES (4, 253, 'home_promo', 'Wagyu Truffle Burger & Hand-Cut Fries', 'Aged gruyère cheese, black truffle aioli, and caramelized balsamic onion jam on brioche.', 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=800&auto=format&fit=crop&q=80', '/shop/aura-bistro', 'Order Bistro Combo', 4, 'CHEF\'S SPECIAL • $5 DISCOUNT', '#8b5cf6', 'rgba(139, 92, 246, 0.95)', 'BISTROVIP', 19.5, 14.5, 'Save $5.00', 'Dinner & lunch service', '#8b5cf6', 1) ON DUPLICATE KEY UPDATE title = VALUES(title), subtitle = VALUES(subtitle), image = VALUES(image), promo_price = VALUES(promo_price), coupon_code = VALUES(coupon_code);
INSERT INTO `aura_theme_posts` (id, biller_id, title, slug, category, badge, duration, excerpt, body, author, status) VALUES (1, 1, 'B2B Procurement & Contract Sourcing', 'b2b-procurement-contract-sourcing', 'Core Program', 'Core Program', '8 Modules • 4 Hours', 'Master wholesale RFQs, volume tier pricing structures, payment escrow terms, and commercial dispute resolution.', 'Complete procurement guide for corporate supply managers. Covers verified factory audits, container freight logistics, proforma invoices, and payment escrow mechanisms.', 'Aura Trade Council', 'published') ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), body = VALUES(body);
INSERT INTO `aura_theme_posts` (id, biller_id, title, slug, category, badge, duration, excerpt, body, author, status) VALUES (2, 1, 'Multi-Store Setup & Telegram E-Menu Dispatch', 'multi-store-setup-telegram-emenu', 'E-Menu System', 'E-Menu System', '6 Modules • 2.5 Hours', 'Step-by-step tutorial on @BotFather integration, table QR code setup, menu category tagging, and automated kitchen routing.', 'Deploy your Telegram Mini App contactless ordering in under 48 hours. Includes table QR generator, staff channel routing, and instant receipt printing setup.', 'Hospitality Tech Lead', 'published') ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), body = VALUES(body);
INSERT INTO `aura_theme_posts` (id, biller_id, title, slug, category, badge, duration, excerpt, body, author, status) VALUES (3, 1, 'Factory Audits & ISO/HACCP Quality Compliance', 'factory-audits-quality-compliance', 'Compliance', 'Compliance', '5 Modules • 3 Hours', 'Guidelines for food safety certifications, direct-trade farm lot traceability, electronics warranty standards, and packaging integrity.', 'Comprehensive guide to international food safety and manufacturing standards, batch traceability, and pre-shipment quality inspection protocols.', 'Quality Assurance Board', 'published') ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), body = VALUES(body);
INSERT INTO `aura_theme_posts` (id, biller_id, title, slug, category, badge, duration, excerpt, body, author, status) VALUES (4, 1, 'Cross-Border Freight & Customs IncoTerms', 'cross-border-freight-customs-incoterms', 'Logistics', 'Logistics', '7 Modules • 3.5 Hours', 'Understanding FOB vs CIF terms, overland transit between Cambodia and Thailand, port handling, and import tax clearance.', 'Practical guide to regional overland and port transit across Cambodia, Thailand, and Vietnam. Learn customs declarations, tax rates, and delivery logistics.', 'Regional Freight Directorate', 'published') ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), body = VALUES(body);
INSERT INTO `aura_theme_posts` (id, biller_id, title, slug, category, badge, duration, excerpt, body, author, status) VALUES (5, 1, 'The Art of Pour-Over Coffee in Southeast Asia', 'art-of-pour-over-coffee', 'Brewing Guide', 'Brewing Guide', '15 min read', 'Discover the precise grind sizes, water temperatures, and filter techniques that bring out highland floral notes.', 'Exploring single-origin Arabica extraction methods, water chemistry, and bloom techniques that highlight natural floral and honey flavors.', 'Chantha Keo', 'published') ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), body = VALUES(body);
